{
  "category_edits": [
    {
      "category": "hyperparameter_tuning",
      "rationale": "Across all four datasets, shorten history to 48 items to reduce convolution cost while covering most observed histories. Lower dropout to retain short-history signal and reduce learning rate to moderate updates with less regularization. Retain hidden size 64, six blocks, batch size 128 and all training caps. Existing checkpoint metadata passes the updated history length to prediction.",
      "edits": [
        {
          "find": "MAXLEN        = int(os.environ.get(\"NEXTITNET_MAXLEN\", \"64\"))",
          "replace": "MAXLEN        = int(os.environ.get(\"NEXTITNET_MAXLEN\", \"48\"))"
        },
        {
          "find": "DROPOUT_RATE  = float(os.environ.get(\"NEXTITNET_DROPOUT\", \"0.15\"))",
          "replace": "DROPOUT_RATE  = float(os.environ.get(\"NEXTITNET_DROPOUT\", \"0.10\"))"
        },
        {
          "find": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"8e-4\"))",
          "replace": "LR            = float(os.environ.get(\"NEXTITNET_LR\", \"6e-4\"))"
        }
      ]
    }
  ],
  "change_summary": "Jointly set NextItNet defaults to history length 48, dropout 0.10 and learning rate 6e-4 for all four category models. Preserve architecture, features, loss, routing and single-checkpoint prediction."
}
